def max_happiness(n, m, moods, subarrays):
    import itertools

    def calculate_happiness(subset):
        flower_coverage = [0] * n
        for l, r in subset:
            for i in range(l - 1, r):
                flower_coverage[i] += 1
        return sum(flower_coverage[i] * moods[i] for i in range(n))

    max_happiness = float('-inf')
    for subset in itertools.chain.from_iterable(
            itertools.combinations(subarrays, r) for r in range(len(subarrays) + 1)):
        max_happiness = max(max_happiness, calculate_happiness(subset))

    return max_happiness

